  const email = 'probe-' + Date.now() + '@example.test';
  const sq = await (await fetch('/api/SecurityQuestions')).json();
  const reg = await fetch('/api/Users', {method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({email, password:'Passw0rd!probe', passwordRepeat:'Passw0rd!probe', securityQuestion:{id: sq.data[0].id, question: sq.data[0].question}, securityAnswer:'x'})});
  const regBody = await reg.text();
  const login = await (await fetch('/rest/user/login', {method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({email, password:'Passw0rd!probe'})})).json();
  const token = login.authentication.token;
  const h = {'content-type':'application/json', authorization: 'Bearer ' + token};
  const addr = await fetch('/api/Addresss', {method:'POST', headers:h, body: JSON.stringify({fullName:'Test Customer', mobileNum:501234567, zipCode:'01001', streetAddress:'1 Khreshchatyk Street', city:'Kyiv', state:'Kyiv', country:'Ukraine'})});
  const card = await fetch('/api/Cards', {method:'POST', headers:h, body: JSON.stringify({fullName:'Test Customer', cardNum:4111111111111111, expMonth:12, expYear:2090})});
  const cardJson = await card.json();
  const topup = await fetch('/rest/wallet/balance', {method:'PUT', headers:h, body: JSON.stringify({balance: 5, paymentId: String(cardJson.data.id)})});
  const wallet = await (await fetch('/rest/wallet/balance', {headers:h})).text();
  return {regStatus: reg.status, regBody: regBody.slice(0,200), sqSample: sq.data[0], addrStatus: addr.status, cardStatus: card.status, cardId: cardJson.data && cardJson.data.id, topupStatus: topup.status, topupBody: (await topup.text()).slice(0,200), wallet};
}

