async (page) => {
  await page.context().addCookies([{name:'cookieconsent_status', value:'dismiss', url:'http://localhost:3000'}]);
  await page.goto('http://localhost:3000/#/search');
  await page.waitForSelector('mat-grid-tile, .mat-mdc-card, .mat-mdc-grid-tile');
  return await page.evaluate(() => {
    const btn = [...document.querySelectorAll('button')].find(b => /Add to Basket/i.test(b.getAttribute('aria-label')||b.textContent));
    const tile = btn && btn.closest('mat-grid-tile, .mat-mdc-card, .mat-mdc-grid-tile, mat-card');
    return {
      btnLabel: btn && btn.getAttribute('aria-label'),
      tileTag: tile && tile.tagName,
      tileClass: tile && tile.className.slice(0,120),
      tileHtml: tile && tile.outerHTML.slice(0, 1500),
      basketButton: [...document.querySelectorAll('button')].filter(b=>/cart|Basket/i.test(b.getAttribute('aria-label')||'')).map(b=>b.outerHTML.slice(0,400)),
      snack: !!document.querySelector('.mat-mdc-snack-bar-container')
    };
  });
}

