import { encode } from 'z85';

// Month codes from test-cases/README.md, in calendar order.
const MONTH_CODES = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/**
 * Builds a coupon code for the given month: Z85 of `<MMM><YY>-<NN>`.
 * Uses the machine date, as README.md requires.
 */
export function buildCoupon(month: Date, percent: number): string {
  const code = MONTH_CODES[month.getMonth()];
  const yy = String(month.getFullYear() % 100).padStart(2, '0');
  const nn = String(percent).padStart(2, '0');
  return encode(`${code}${yy}-${nn}`) as string;
}

/** The 10% coupon of the current month. */
export function currentMonthCoupon(): string {
  return buildCoupon(new Date(), 10);
}

/** The 10% coupon of the previous month. It is expired. */
export function previousMonthCoupon(): string {
  const now = new Date();
  return buildCoupon(new Date(now.getFullYear(), now.getMonth() - 1, 1), 10);
}

