import type { APIRequestContext } from '@playwright/test';
import { SAVED_ADDRESS, SAVED_CARD } from './testData';

export interface Customer {
  email: string;
  password: string;
  token: string;
  cardId: number;
}

const JSON_HEADERS = { 'content-type': 'application/json' };

/**
 * Creates a new normal customer account with a unique email, a saved address
 * and a saved card, as the preconditions of the test cases require.
 */
export async function createCustomer(request: APIRequestContext, prefix: string): Promise<Customer> {
  const email = `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}@example.test`;
  const password = `Passw0rd!${prefix}`;

  const questions = await (await request.get('/api/SecurityQuestions')).json();
  const register = await request.post('/api/Users', {
    headers: JSON_HEADERS,
    data: {
      email,
      password,
      passwordRepeat: password,
      securityQuestion: { id: questions.data[0].id, question: questions.data[0].question },
      securityAnswer: 'test',
    },
  });
  if (!register.ok()) {
    throw new Error(`Registration failed: ${register.status()} ${await register.text()}`);
  }

  const token = await loginByApi(request, email, password);
  const auth = { ...JSON_HEADERS, authorization: `Bearer ${token}` };

  const address = await request.post('/api/Addresss', {
    headers: auth,
    data: {
      fullName: SAVED_ADDRESS.name,
      mobileNum: SAVED_ADDRESS.mobileNumber,
      zipCode: SAVED_ADDRESS.zip,
      streetAddress: SAVED_ADDRESS.address,
      city: SAVED_ADDRESS.city,
      state: SAVED_ADDRESS.state,
      country: SAVED_ADDRESS.country,
    },
  });
  if (!address.ok()) {
    throw new Error(`Saving the address failed: ${address.status()} ${await address.text()}`);
  }

  const card = await request.post('/api/Cards', {
    headers: auth,
    data: {
      fullName: SAVED_CARD.name,
      cardNum: SAVED_CARD.number,
      expMonth: SAVED_CARD.expiryMonth,
      expYear: SAVED_CARD.expiryYear,
    },
  });
  if (!card.ok()) {
    throw new Error(`Saving the card failed: ${card.status()} ${await card.text()}`);
  }
  const cardId = (await card.json()).data.id as number;

  return { email, password, token, cardId };
}

export async function loginByApi(request: APIRequestContext, email: string, password: string): Promise<string> {
  const response = await request.post('/rest/user/login', {
    headers: JSON_HEADERS,
    data: { email, password },
  });
  if (!response.ok()) {
    throw new Error(`Login failed: ${response.status()} ${await response.text()}`);
  }
  return (await response.json()).authentication.token as string;
}

/** Adds money to the wallet of the customer. The top-up uses the saved card. */
export async function topUpWallet(request: APIRequestContext, customer: Customer, amount: number): Promise<void> {
  const response = await request.put('/rest/wallet/balance', {
    headers: { ...JSON_HEADERS, authorization: `Bearer ${customer.token}` },
    data: { balance: amount, paymentId: String(customer.cardId) },
  });
  if (!response.ok()) {
    throw new Error(`Wallet top-up failed: ${response.status()} ${await response.text()}`);
  }
}

