import { test as base, expect } from '@playwright/test';
import { type Customer, createCustomer } from './accounts';
import { BASE_URL } from './testData';
import { LoginPage } from '../pages/LoginPage';

type Fixtures = {
  /** A new normal customer with a saved address and a saved card. */
  customer: Customer;
};

export const test = base.extend<Fixtures>({
  // The cookie banner hides itself with this cookie (test-cases/README.md).
  context: async ({ context }, use) => {
    await context.addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: BASE_URL }]);
    await use(context);
  },

  customer: async ({ request }, use, testInfo) => {
    await use(await createCustomer(request, testInfo.title.slice(0, 5).toLowerCase().replace(/[^a-z0-9]/g, '')));
  },
});

export { expect };

/** Logs the customer in through the login page, the way a customer does. */
export async function logIn(page: import('@playwright/test').Page, customer: Customer): Promise<void> {
  await new LoginPage(page).open();
  await new LoginPage(page).logIn(customer.email, customer.password);
  await expect(page).toHaveURL(/#\/search$/);
}

