export class BasketPage {
  readonly checkoutButton: Locator;

  constructor(private readonly page: Page) {
    this.checkoutButton = page.getByRole('button', { name: 'Checkout' });
  }

  async open(): Promise<void> {
    await this.page.goto('/#/basket');
    await expect(this.page).toHaveURL(/#\/basket$/);
  }

  /** The table row of the product in the basket. */
  row(name: string): Locator {
    return this.page.locator('mat-row, .mat-mdc-row').filter({ hasText: name });
  }

  /** The plus, minus or trash button of the product row. The icon names the button. */
  rowButton(name: string, icon: 'add' | 'remove' | 'delete'): Locator {
    return this.row(name).locator('button').filter({ has: this.page.locator('mat-icon', { hasText: new RegExp(`^${icon}$`) }) });
  }

  async increase(name: string): Promise<void> {
    await this.rowButton(name, 'add').click();
  }

  async decrease(name: string): Promise<void> {
    await this.rowButton(name, 'remove').click();
  }

  async remove(name: string): Promise<void> {
    await this.rowButton(name, 'delete').click();
  }

  /** The quantity shown in the row of the product. */
  async quantity(name: string): Promise<number> {
    return Number(await this.row(name).locator('.mat-column-quantity, [class*="quantity"]').first().innerText());
  }

  totalPrice(total: string): Locator {
    return this.page.getByText(`Total Price: ${total}`);
  }

  async checkout(): Promise<void> {
    await this.checkoutButton.click();
  }
}

