import { expect, type Locator, type Page } from '@playwright/test';

/** The top bar of the shop: account menu, basket button and snack bar messages. */
export class TopBar {
  readonly accountButton: Locator;
  readonly basketButton: Locator;
  readonly menu: Locator;

  constructor(private readonly page: Page) {
    this.accountButton = page.locator('#navbarAccount');
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.menu = page.getByRole('menu');
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expect(this.menu).toBeVisible();
  }

  /** Closes an open menu with the Escape key. */
  async closeMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expect(this.menu).toBeHidden();
  }

  /** Clicks an item of the open account menu. The name is matched by part of the text, case-insensitive. */
  async clickMenuItem(name: string): Promise<void> {
    await this.menu.getByRole('menuitem', { name: new RegExp(name, 'i') }).click();
  }

  /** The number shown on the basket button. */
  async basketCount(): Promise<number> {
    const text = (await this.basketButton.innerText()).trim();
    return Number(text.split(/\s+/).pop());
  }

  async openBasket(): Promise<void> {
    await this.basketButton.click();
    await expect(this.page).toHaveURL(/#\/basket$/);
  }

  /** Waits until the snack bar shows the text. */
  async expectSnackBar(text: string): Promise<void> {
    await expect(this.page.locator('.mat-mdc-snack-bar-container')).toContainText(text);
  }
}

