import { test, expect, logIn } from './support/fixtures';
import { currentMonthCoupon } from './support/coupon';
import { DELIVERY, PRODUCTS, SAVED_ADDRESS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';
import { AddressPage, DeliveryPage, OrderSummaryPage, PaymentPage } from '../pages/CheckoutPages';

test('TC-05: Valid coupon on the payment step', async ({ page, customer }) => {
  const products = new ProductListPage(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);
  const product = PRODUCTS.eggfruit;

  await logIn(page, customer);

  // Preconditions: the basket holds the product with quantity 2.
  await products.open();
  await products.addToBasket(product);
  await products.addToBasket(product);
  await basket.open();
  expect(await basket.quantity(product)).toBe(2);

  await test.step('1. Open the basket and click Checkout. The saved address is shown', async () => {
    await basket.checkout();
    await addressPage.expectOpen();
    await expect(addressPage.savedAddress(SAVED_ADDRESS.address)).toBeVisible();
  });

  await test.step('2. Select the saved address and click Continue. Delivery options and prices are shown', async () => {
    await addressPage.select(SAVED_ADDRESS.address);
    await addressPage.continue();
    await deliveryPage.expectOpen();
    await expect(deliveryPage.option(DELIVERY.oneDay)).toContainText('0.99¤');
    await expect(deliveryPage.option(DELIVERY.fast)).toContainText('0.50¤');
    await expect(deliveryPage.option(DELIVERY.standard)).toContainText('0.00¤');
  });

  await test.step('3. Select One Day Delivery and click Continue. The payment page shows the card and the coupon panel', async () => {
    await deliveryPage.select(DELIVERY.oneDay);
    await deliveryPage.continue();
    await paymentPage.expectOpen();
    await expect(paymentPage.savedCard()).toBeVisible();
    await expect(paymentPage.couponPanelHeader).toBeVisible();
  });

  await test.step('4. Open the coupon panel, redeem the coupon of this month. The discount message shows', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(currentMonthCoupon());
    await expect(page.getByText('Your discount of 10% will be applied during checkout.')).toBeVisible();
  });

  await test.step('5. Select the saved card and click Continue. The order summary shows the discount', async () => {
    await paymentPage.selectCard();
    await paymentPage.continue();
    await summary.expectOpen();
    await expect(summary.line('Items')).toContainText('17.98¤');
    await expect(summary.line('Delivery')).toContainText('0.99¤');
    await expect(summary.line('Promotion')).toContainText('1.80¤');
    await expect(summary.line('Total Price')).toContainText('17.17¤');
  });
});

