  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);
  const product = PRODUCTS.eggfruit;

  await logIn(page, customer);

  // Preconditions: the basket holds the product with quantity 2.
  await products.open();
  await products.addToBasket(product);
  await products.addToBasket(product);
  await basket.open();
  expect(await basket.quantity(product)).toBe(2);

  await test.step('1. Open the basket, click Checkout, select the saved address and click Continue', async () => {
    await basket.checkout();
    await addressPage.select(SAVED_ADDRESS.address);
    await addressPage.continue();
    await deliveryPage.expectOpen();
  });

  await test.step('2. Select One Day Delivery and click Continue. The payment page opens', async () => {
    await deliveryPage.select(DELIVERY.oneDay);
    await deliveryPage.continue();
    await paymentPage.expectOpen();
  });

  await test.step('3. Redeem the invalid code. The shop shows Invalid coupon. and no discount', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(INVALID_COUPON);
    await expect(page.getByText('Invalid coupon.')).toBeVisible();
    await expect(page.getByText('Your discount of')).toHaveCount(0);
  });

  await test.step('4. Redeem the expired coupon. The shop shows Invalid coupon. and no discount', async () => {
    await paymentPage.redeemCoupon(previousMonthCoupon());
