  await test.step('5. Select the saved card and click Continue. The summary has no promotion', async () => {
    await paymentPage.selectCard();
    await paymentPage.continue();
    await summary.expectOpen();
    await expect(summary.line('Items')).toContainText('17.98¤');
    await expect(summary.line('Delivery')).toContainText('0.99¤');
    await expect(summary.line('Promotion')).toContainText('0.00¤');
    await expect(summary.line('Total Price')).toContainText('18.97¤');
  });
});

