import { expect, type Locator, type Page } from '@playwright/test';

export class BasketPage {
  readonly checkoutButton: Locator;

  constructor(private readonly page: Page) {
    this.checkoutButton = page.getByRole('button', { name: 'Checkout' });
  }

  async open(): Promise<void> {
    await this.page.goto('/#/basket');
    await expect(this.page).toHaveURL(/#\/basket$/);
  }

  /** The table row of the product in the basket. */
  row(name: string): Locator {
    return this.page.getByRole('row').filter({ hasText: name });
  }

  /**
   * The plus, minus or trash button of the product row. The buttons have no text,
   * only an icon, so they are found by the icon name.
   */
  rowButton(name: string, icon: 'plus-square' | 'minus-square' | 'trash-alt'): Locator {
    return this.row(name).locator('button').filter({ has: this.page.locator(`[data-icon="${icon}"], .fa-${icon}`) });
  }

  async increase(name: string): Promise<void> {
    await this.rowButton(name, 'plus-square').click();
  }

  async decrease(name: string): Promise<void> {
    await this.rowButton(name, 'minus-square').click();
  }

  async remove(name: string): Promise<void> {
    await this.rowButton(name, 'trash-alt').click();
  }

  /** The quantity shown in the row of the product. The quantity is the third cell. */
  async quantity(name: string): Promise<number> {
    return Number((await this.row(name).getByRole('cell').nth(2).innerText()).trim());
  }

  totalPrice(total: string): Locator {
    return this.page.getByText(`Total Price: ${total}`);
  }

  async checkout(): Promise<void> {
    await this.checkoutButton.click();
  }
}

