import { test, expect, logIn } from './support/fixtures';
import { DELIVERY, PRODUCTS, SAVED_ADDRESS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';
import { AddressPage, DeliveryPage, PaymentPage } from '../pages/CheckoutPages';

test('debug payment page', async ({ page, customer }) => {
  await logIn(page, customer);
  await new ProductListPage(page).addToBasket(PRODUCTS.eggfruit);
  const basket = new BasketPage(page);
  await basket.open();
  await basket.checkout();
  const address = new AddressPage(page);
  await address.select(SAVED_ADDRESS.address);
  await address.continue();
  const delivery = new DeliveryPage(page);
  await delivery.select(DELIVERY.oneDay);
  await delivery.continue();
  await new PaymentPage(page).expectOpen();
  await page.waitForTimeout(3000);
  const info = await page.evaluate(() => ({
    buttons: [...document.querySelectorAll('button')].map((b) => JSON.stringify(b.textContent?.trim().slice(0, 60))),
    wallet: [...document.querySelectorAll('div')].filter((d) => d.textContent?.includes('Pay using wallet')).map((d) => d.outerHTML.slice(0, 400)).slice(-2),
    url: location.href,
  }));
  console.log(JSON.stringify(info, null, 2));
  await page.screenshot({ path: 'debug-payment.png', fullPage: true });
});

