import { test, logIn } from './support/fixtures';
import { PRODUCTS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';

test('debug basket timing', async ({ page, customer }) => {
  const t0 = Date.now();
  const log = (msg: string) => console.log(`[${Date.now() - t0}ms] ${msg}`);
  page.on('response', (r) => {
    if (/basket|Basket/.test(r.url())) log(`RESPONSE ${r.request().method()} ${r.url().replace('http://localhost:3000', '')} -> ${r.status()}`);
  });
  await logIn(page, customer);
  log('logged in');
  await new ProductListPage(page).addToBasket(PRODUCTS.eggfruit);
  log('clicked add');
  const basket = new BasketPage(page);
  await basket.open();
  log('basket opened and reloaded');
  for (const s of [0, 2, 5, 10]) {
    await page.waitForTimeout(s === 0 ? 0 : 2000);
    log(`rows=${await basket.row(PRODUCTS.eggfruit).count()} checkoutDisabled=${await basket.checkoutButton.isDisabled()} sessionBid=${await page.evaluate(() => sessionStorage.getItem('bid'))}`);
  }
});

