import { expect, type Locator, type Page } from '@playwright/test';

export class ProductListPage {
  constructor(private readonly page: Page) {}

  /** Opens the product list /#/search and waits until its products are loaded. */
  async open(): Promise<void> {
    await this.load('/#/search');
  }

  /** Shows the product list filtered by the product name, as the search does. */
  async searchFor(name: string): Promise<void> {
    await this.load(`/#/search?q=${encodeURIComponent(name)}`);
    await expect(this.productCard(name)).toBeVisible();
  }

  /** The card of the product, found by its image name. */
  productCard(name: string): Locator {
    return this.page.locator('mat-card').filter({ has: this.page.getByRole('img', { name, exact: true }) });
  }

  /**
   * Searches for the product, then clicks Add to Basket on its card.
   * Waits for the server to answer the request, so the next navigation does not cancel it.
   */
  async addToBasket(name: string): Promise<void> {
    await this.searchFor(name);
    await Promise.all([
      this.page.waitForResponse((response) => response.url().includes('/api/BasketItems') && response.request().method() === 'POST'),
      this.productCard(name).getByRole('button', { name: 'Add to Basket' }).click(),
    ]);
  }

  /**
   * Navigates to the list. Under load the app can render the list before its products
   * arrive, and a hash change does not load them again. In that case the page is reloaded.
   */
  private async load(url: string): Promise<void> {
    await this.page.goto(url);
    const firstCard = this.page.locator('mat-card').first();
    await expect(async () => {
      const shown = await firstCard.waitFor({ state: 'visible', timeout: 3_000 }).then(() => true, () => false);
      if (!shown) {
        await this.page.reload();
        throw new Error('The product list is empty. The page was reloaded.');
      }
    }).toPass({ timeout: 60_000 });
  }
}

import { expect, type Locator, type Page } from '@playwright/test';

/** The checkout steps in order: address, delivery, payment, order summary. */

/** A button found by its visible text. Its accessible name can differ, for example "Proceed to payment selection". */
function buttonWithText(page: Page, text: string): Locator {
  return page.locator('button').filter({ hasText: text });
}

export class AddressPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page.getByRole('heading', { name: 'Select an address' })).toBeVisible();
  }

  /** The table row of the saved address, found by its street. */
  savedAddress(street: string): Locator {
    return this.page.getByRole('row').filter({ hasText: street });
  }

  async select(street: string): Promise<void> {
    await this.savedAddress(street).click();
  }

  async continue(): Promise<void> {
    await buttonWithText(this.page, 'Continue').click();
  }
}

export class DeliveryPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page.getByText('Choose a delivery speed')).toBeVisible();
  }

  /** The row of the delivery option, with its name and price. */
  option(name: string): Locator {
    return this.page.getByRole('row').filter({ hasText: name });
  }

  async select(name: string): Promise<void> {
    await this.option(name).click();
  }

  async continue(): Promise<void> {
    await buttonWithText(this.page, 'Continue').click();
  }
}

export class PaymentPage {
  readonly couponPanelHeader: Locator;
  readonly couponField: Locator;
  readonly redeemButton: Locator;

  constructor(private readonly page: Page) {
    this.couponPanelHeader = buttonWithText(page, 'Add a coupon');
    this.couponField = page.getByRole('textbox', { name: /coupon/i });
    this.redeemButton = page.getByRole('button', { name: 'Redeem' });
  }

  async expectOpen(): Promise<void> {
    await expect(this.page.getByText('My Payment Options')).toBeVisible();
  }

  /** The row of the saved card. The card number is masked and ends with 1111. */
  savedCard(): Locator {
    return this.page.getByRole('row').filter({ hasText: '1111' });
  }

  async selectCard(): Promise<void> {
    await this.savedCard().click();
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanelHeader.click();
    await expect(this.couponField).toBeVisible();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponField.fill(code);
    await this.redeemButton.click();
  }

  async continue(): Promise<void> {
    await buttonWithText(this.page, 'Continue').click();
  }

  /** The wallet payment option, which shows the wallet balance. */
  walletOption(): Locator {
    return this.page.locator('div').filter({ hasText: 'Pay using wallet' }).last();
  }

  /** The button that pays with the wallet, for example "Pay 8.99¤". */
  payWithWalletButton(total: string): Locator {
    return buttonWithText(this.page, `Pay ${total}`);
  }
}

export class OrderSummaryPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page.getByText('Order Summary').first()).toBeVisible();
  }

  /** The line of the summary, for example "Items" or "Total Price". */
  line(label: 'Items' | 'Delivery' | 'Promotion' | 'Total Price'): Locator {
    return this.page.getByRole('row').filter({ has: this.page.getByText(label, { exact: true }) });
  }

  async placeOrderAndPay(): Promise<void> {
    await buttonWithText(this.page, 'Place your order and pay').click();
  }
}

