import { test, expect, logIn } from './support/fixtures';
import { currentMonthCoupon } from './support/coupon';
import { DELIVERY, PRODUCTS, SAVED_ADDRESS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';
import { TopBar } from '../pages/TopBar';
import { AddressPage, DeliveryPage, OrderSummaryPage, PaymentPage } from '../pages/CheckoutPages';
import { OrderCompletionPage, OrderHistoryPage } from '../pages/OrderPages';

test('TC-07: Order with a card, from basket to order history', async ({ page, customer }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);
  const completion = new OrderCompletionPage(page);
  const history = new OrderHistoryPage(page);
  const productA = PRODUCTS.eggfruit;
  const productB = PRODUCTS.carrot;

  await logIn(page, customer);
  let orderId = '';

  await test.step('1. Add product A two times and product B one time. Counter is 3', async () => {
    await products.open();
    await products.addToBasket(productA);
    await products.addToBasket(productA);
    await products.addToBasket(productB);
    await expect.poll(() => topBar.basketCount()).toBe(3);
  });

  await test.step('2. Open the basket. A: quantity 2, B: quantity 1, Total 20.97¤', async () => {
    await basket.open();
    expect(await basket.quantity(productA)).toBe(2);
    expect(await basket.quantity(productB)).toBe(1);
    await expect(basket.totalPrice('20.97¤')).toBeVisible();
  });

  await test.step('3. Click Checkout, select the saved address and click Continue', async () => {
    await basket.checkout();
    await addressPage.select(SAVED_ADDRESS.address);
    await addressPage.continue();
    await deliveryPage.expectOpen();
  });

  await test.step('4. Select One Day Delivery and click Continue', async () => {
    await deliveryPage.select(DELIVERY.oneDay);
    await deliveryPage.continue();
    await paymentPage.expectOpen();
  });

  await test.step('5. Redeem the coupon of this month. The discount message shows', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(currentMonthCoupon());
    await expect(page.getByText('Your discount of 10% will be applied during checkout.')).toBeVisible();
  });

  await test.step('6. Select the saved card and click Continue. The order summary shows the totals', async () => {
    await paymentPage.selectCard();
    await paymentPage.continue();
    await summary.expectOpen();
    await expect(page.getByText(SAVED_ADDRESS.address).first()).toBeVisible();
    await expect(paymentPage.savedCard()).toBeVisible();
    await expect(summary.line('Items')).toContainText('20.97¤');
    await expect(summary.line('Delivery')).toContainText('0.99¤');
    await expect(summary.line('Promotion')).toContainText('2.10¤');
    await expect(summary.line('Total Price')).toContainText('19.86¤');
  });

  await test.step('7. Click Place your order and pay. The confirmation page opens with the order ID', async () => {
    await summary.placeOrderAndPay();
    orderId = await completion.expectOpen();
    expect(orderId).not.toBe('');
  });

  await test.step('8. The confirmation shows the products, Items, Delivery, Promotion and Total Price', async () => {
    await expect(completion.product(productA)).toContainText('2');
    await expect(completion.product(productB)).toContainText('1');
    await expect(completion.line('Items')).toContainText('20.97¤');
    await expect(completion.line('Delivery')).toContainText('0.99¤');
    await expect(completion.line('Promotion')).toContainText('2.10¤');
    await expect(completion.line('Total Price')).toContainText('19.86¤');
  });

  await test.step('9. The basket is empty and Checkout is disabled', async () => {
    await expect.poll(() => topBar.basketCount()).toBe(0);
    await basket.open();
    await expect(basket.row(productA)).toHaveCount(0);
    await expect(basket.row(productB)).toHaveCount(0);
    await expect(basket.checkoutButton).toBeDisabled();
  });

  await test.step('10. Order History shows the order with Total Price 19.86¤ and the two products', async () => {
    await topBar.openAccountMenu();
    await topBar.clickMenuItem('Orders & Payment');
    await topBar.clickMenuItem('Order History');
    await history.expectOpen();
    const order = history.order(orderId);
    await expect(order).toBeVisible();
    await expect(order).toContainText('19.86¤');
    await expect(order).toContainText(productA);
    await expect(order).toContainText(productB);
  });
});

import { test, expect, logIn } from './support/fixtures';
import { topUpWallet } from './support/accounts';
import { DELIVERY, PRODUCTS, SAVED_ADDRESS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';
import { TopBar } from '../pages/TopBar';
import { AddressPage, DeliveryPage, OrderSummaryPage, PaymentPage } from '../pages/CheckoutPages';
import { OrderCompletionPage, OrderHistoryPage, WalletPage } from '../pages/OrderPages';

test('TC-08: Payment with the wallet', async ({ page, request, customer }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);
  const completion = new OrderCompletionPage(page);
  const history = new OrderHistoryPage(page);
  const wallet = new WalletPage(page);
  const product = PRODUCTS.eggfruit;
  const orderTotal = '8.99¤';

  // Preconditions: the wallet holds 5.00¤ and the basket holds the product with quantity 1.
  await topUpWallet(request, customer, 5);
  await logIn(page, customer);
  await products.open();
  await products.addToBasket(product);
  await expect.poll(() => topBar.basketCount()).toBe(1);

  // Opens the basket, then goes through address and delivery to the payment page.
  async function goToPaymentWithStandardDelivery(): Promise<void> {
    await basket.open();
    await basket.checkout();
    await addressPage.select(SAVED_ADDRESS.address);
    await addressPage.continue();
    await deliveryPage.select(DELIVERY.standard);
    await deliveryPage.continue();
    await paymentPage.expectOpen();
  }

  await test.step('Part 1 / 1. Open the basket, click Checkout, select the saved address and click Continue', async () => {
    await basket.open();
    await basket.checkout();
    await addressPage.select(SAVED_ADDRESS.address);
    await addressPage.continue();
    await deliveryPage.expectOpen();
  });

  await test.step('Part 1 / 2. Select Standard Delivery and click Continue. Wallet balance 5.00 and Pay 8.99¤ are shown', async () => {
    await deliveryPage.select(DELIVERY.standard);
    await deliveryPage.continue();
    await paymentPage.expectOpen();
    await expect(paymentPage.walletOption()).toContainText('5.00');
    await expect(paymentPage.payWithWalletButton(orderTotal)).toBeVisible();
  });

  await test.step('Part 1 / 3. The Pay 8.99¤ button is disabled', async () => {
    await expect(paymentPage.payWithWalletButton(orderTotal)).toBeDisabled();
  });

  await test.step('Part 1 / 4. Order History says there are no orders yet', async () => {
    await topBar.openAccountMenu();
    await topBar.clickMenuItem('Orders & Payment');
    await topBar.clickMenuItem('Order History');
    await expect(page.getByText('You have not placed any orders yet.')).toBeVisible();
  });

  await test.step('Part 1 / 5. Digital Wallet shows balance 5.00', async () => {
    await topBar.openAccountMenu();
    await topBar.clickMenuItem('Orders & Payment');
    await topBar.clickMenuItem('Digital Wallet');
    await wallet.expectOpen();
    await expect(wallet.balance()).toContainText('5.00');
  });

  // Part 2 starts with the wallet at exactly the order total. The top-up uses the saved card.
  await topUpWallet(request, customer, 3.99);

  await test.step('Part 2 / 6. Go to the payment page with Standard Delivery. Wallet balance 8.99 and an enabled Pay 8.99¤', async () => {
    await goToPaymentWithStandardDelivery();
    await expect(paymentPage.walletOption()).toContainText('8.99');
    await expect(paymentPage.payWithWalletButton(orderTotal)).toBeEnabled();
  });

  await test.step('Part 2 / 7. Click Pay 8.99¤. The order summary shows Digital Wallet and Total Price 8.99¤', async () => {
