import { expect, type Locator, type Page } from '@playwright/test';

export class OrderCompletionPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<string> {
    await expect(this.page).toHaveURL(/#\/order-completion\/.+$/);
    await expect(this.page.getByText('Thank you for your purchase!')).toBeVisible();
    return this.orderId();
  }

  /** The order ID from the URL `/#/order-completion/<order ID>`. */
  orderId(): string {
    return new URL(this.page.url()).hash.split('/').pop() as string;
  }

  /**
   * The line of the order summary, for example "Items" or "Total Price".
   * Only the body rows (tr) count. The table footer also lists the labels in one row.
   */
  line(label: 'Items' | 'Delivery' | 'Promotion' | 'Total Price'): Locator {
    return this.page.locator('tr').filter({ has: this.page.getByRole('cell', { name: label, exact: true }) });
  }

  /** The row of a product: its name, quantity and price. */
  product(name: string): Locator {
    return this.page.getByRole('row').filter({ hasText: name });
  }
}

export class OrderHistoryPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page).toHaveURL(/#\/order-history$/);
    await expect(this.page.getByText('Order History').first()).toBeVisible();
  }

  /** The card of one order, found by its order ID. */
  order(orderId: string): Locator {
    return this.page.locator('mat-card, .mat-mdc-card').filter({ hasText: orderId }).first();
  }
}

export class WalletPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page).toHaveURL(/#\/wallet$/);
    await expect(this.page.getByText('Digital Wallet').first()).toBeVisible();
  }

  /** The element that holds the wallet balance. */
  balance(): Locator {
    return this.page.locator('#wallet-balance, .wallet-balance, mat-card, div').filter({ hasText: /Wallet Balance/ }).last();
  }
}

